from datetime import datetime, timedelta, timezone

_STATES = {"paid": "open", "refunded": "void"}
_CURRENCIES = {"EUR", "USD", "GBP"}


def _money(cents):
    if not isinstance(cents, int) or isinstance(cents, bool) or cents < 0:
        raise ValueError(f"bad amount: {cents!r}")
    return f"{cents // 100}.{cents % 100:02d}"


def order_to_invoice(order, offset_minutes):
    created = datetime.fromisoformat(order["created_at"])
    if created.tzinfo is None:
        raise ValueError("created_at has no time zone")
    local = created.astimezone(timezone(timedelta(minutes=offset_minutes)))

    customer = order.get("customer") or {}
    parts = [(customer.get(k) or "").strip() for k in ("first_name", "last_name")]
    name = " ".join(p for p in parts if p)
    if not name:
        raise ValueError("customer name missing")

    email = (customer.get("email") or "").strip().lower()
    local_part, at, domain = email.partition("@")
    if not at or not local_part or not domain or "@" in domain:
        raise ValueError("bad email")

    currency = order.get("currency")
    if currency not in _CURRENCIES:
        raise ValueError(f"unsupported currency: {currency}")

    status = order.get("status")
    if status not in _STATES:
        raise ValueError(f"unmapped status: {status}")

    total = order.get("total_cents")
    amount = _money(total)
    lines, line_total = [], 0
    for line in order.get("lines", []):
        qty = line.get("qty")
        if not isinstance(qty, int) or isinstance(qty, bool) or qty < 1:
            raise ValueError(f"bad quantity: {qty!r}")
        unit = line.get("unit_cents")
        lines.append({"code": line.get("sku"), "quantity": qty, "unit_price": _money(unit)})
        line_total += qty * unit
    if line_total != total:
        raise ValueError("total does not match lines")

    return {
        "external_ref": f"shop-{order['id']}",
        "date": local.date().isoformat(),
        "customer_name": name,
        "email": email,
        "currency": currency,
        "amount": amount,
        "state": _STATES[status],
        "lines": lines,
    }

