import copy

ORDER = {"id": "1001", "created_at": "2026-11-19T23:30:00Z", "currency": "EUR", "total_cents": 2497, "status": "paid",
         "customer": {"first_name": "Ada", "last_name": "Lovelace", "email": " Ada@Example.com "},
         "lines": [{"sku": "BK-1", "qty": 2, "unit_cents": 999}, {"sku": "PEN", "qty": 1, "unit_cents": 499}]}

def changed(**updates):
    o = copy.deepcopy(ORDER)
    for path, value in updates.items():
        target = o
        keys = path.split("__")
        for k in keys[:-1]:
            target = target[k]
        if value is ...:
            target.pop(keys[-1], None)
        else:
            target[keys[-1]] = value
    return o

def problem(order, offset=60):
    try:
        order_to_invoice(order, offset)
    except ValueError as e:
        return str(e)
    return "ok"

@test("the example order")
def _():
    inv = order_to_invoice(ORDER, 60)
    check_eq(inv, {"external_ref": "shop-1001", "date": "2026-11-20", "customer_name": "Ada Lovelace", "email": "ada@example.com",
                   "currency": "EUR", "amount": "24.97", "state": "open",
                   "lines": [{"code": "BK-1", "quantity": 2, "unit_price": "9.99"}, {"code": "PEN", "quantity": 1, "unit_price": "4.99"}]})
    check_eq(list(inv), ["external_ref", "date", "customer_name", "email", "currency", "amount", "state", "lines"])

@test("dates in other zones")
def _():
    check_eq(order_to_invoice(ORDER, 0)["date"], "2026-11-19")
    check_eq(order_to_invoice(ORDER, -300)["date"], "2026-11-19")
    check_eq(order_to_invoice(changed(created_at="2026-11-30T23:30:00+00:00"), 60)["date"], "2026-12-01")
    check_eq(order_to_invoice(changed(created_at="2026-12-01T00:30:00+01:00"), 0)["date"], "2026-11-30")
    check_eq(problem(changed(created_at="2026-11-19T23:30:00")), "created_at has no time zone")

@test("names, emails and money")
def _():
    check_eq(order_to_invoice(changed(customer__last_name=None), 60)["customer_name"], "Ada")
    check_eq(order_to_invoice(changed(customer__first_name=...), 60)["customer_name"], "Lovelace")
    check_eq(problem(changed(customer__first_name="  ", customer__last_name=None)), "customer name missing")
    for bad in ("ada.example.com", "@example.com", "ada@", "a@b@c"):
        check_eq(problem(changed(customer__email=bad)), "bad email")
    o = changed(total_cents=5, lines=[{"sku": "S", "qty": 5, "unit_cents": 1}])
    check_eq(order_to_invoice(o, 0)["amount"], "0.05")
    check_eq(order_to_invoice(changed(total_cents=0, lines=[]), 0)["amount"], "0.00")

@test("statuses and currencies")
def _():
    check_eq(order_to_invoice(changed(status="refunded"), 60)["state"], "void")
    check("partially_refunded" in problem(changed(status="partially_refunded")))
    check_eq(problem(changed(currency="JPY")), "unsupported currency: JPY")

@test("lines and totals")
def _():
    check_eq(problem(changed(total_cents=2498)), "total does not match lines")
    check(problem(changed(lines=[{"sku": "X", "qty": 0, "unit_cents": 2497}])).startswith("bad quantity"))
    check(problem(changed(lines=[{"sku": "X", "qty": True, "unit_cents": 2497}])).startswith("bad quantity"))
    check(problem(changed(total_cents=24.97)).startswith("bad amount"))
    check(problem(changed(total_cents=-1, lines=[])).startswith("bad amount"))

